package com.hms.website;
import com.hms.tenancy.*; import java.time.OffsetDateTime; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}") public class PublicSeoController {private final TenantRepository tenants;private final WebsitePageRepository pages;private final WebsiteContentRepository content;public PublicSeoController(TenantRepository t,WebsitePageRepository p,WebsiteContentRepository c){tenants=t;pages=p;content=c;} @GetMapping(value="/sitemap.xml",produces=MediaType.APPLICATION_XML_VALUE) public ResponseEntity<String> sitemap(@PathVariable String tenantSlug){UUID tenant=activeTenant(tenantSlug);String base="/hospital/"+tenantSlug;StringBuilder xml=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">");xml.append(url(base));pages.findAllByTenantIdAndStatusOrderByTitleAsc(tenant,PageStatus.PUBLISHED).forEach(p->xml.append(url(base+"/pages/"+p.getSlug())));content.findAllByTenantIdAndStatusOrderByPublishedAtDesc(tenant,ContentStatus.PUBLISHED).forEach(c->xml.append(url(base+"/content/"+c.getSlug())));xml.append("</urlset>");return ResponseEntity.ok().contentType(MediaType.APPLICATION_XML).body(xml.toString());} @GetMapping(value="/robots.txt",produces=MediaType.TEXT_PLAIN_VALUE) public ResponseEntity<String> robots(@PathVariable String tenantSlug){activeTenant(tenantSlug);return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).body("User-agent: *\nAllow: /hospital/"+tenantSlug+"\nSitemap: /api/public/hospitals/"+tenantSlug+"/sitemap.xml\n");} private String url(String value){return "<url><loc>"+value.replace("&","&amp;").replace("<","&lt;")+"</loc></url>";} private UUID activeTenant(String slug){return tenants.findBySlug(slug).filter(t->t.getStatus()!=TenantStatus.SUSPENDED&&t.getStatus()!=TenantStatus.CANCELLED&&t.getStatus()!=TenantStatus.EXPIRED).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
